/**
 * /api/businesses/:businessId/products
 * PUT /:id creates or replaces (ids are generated by the web app); POST / lets the server pick the id.
 */
import crypto from 'node:crypto';
import { asc, eq } from 'drizzle-orm';
import { Router, type Request, type Response } from 'express';
import { requireAuth, requireBusiness, requireRole } from '../lib/auth.js';
import { businessIdOf, inBusiness, notFound, parse, pgCode, PG, param } from '../lib/http.js';
import { products } from '../db/schema.js';
import { Id } from '../schemas/common.js';
import { ProductInput } from '../schemas/masters.js';

export const productRoutes = Router({ mergeParams: true });
productRoutes.use(requireAuth, requireBusiness);
const canWrite = requireRole('owner', 'accountant');

type Row = typeof products.$inferSelect;
export const toProductDto = (p: Row) => ({
  id: p.id, businessId: p.businessId, name: p.name, hsCode: p.hsCode, uoM: p.uoM, saleType: p.saleType, rate: p.rate, unitPrice: p.unitPrice,
});

productRoutes.get('/', async (req, res) => {
  const rows = await inBusiness(req, tx => tx.select().from(products).orderBy(asc(products.name)));
  res.json(rows.map(toProductDto));
});

productRoutes.get('/:id', async (req, res) => {
  const [row] = await inBusiness(req, tx => tx.select().from(products).where(eq(products.id, param(req, 'id'))));
  return row ? res.json(toProductDto(row)) : notFound(res, 'Product');
});

async function save(req: Request, res: Response, id: string, created: number) {
  if (!Id.safeParse(id).success) return res.status(400).json({ code: 'VALIDATION', message: 'Invalid id', issues: [{ path: 'id', message: 'Invalid id' }] });
  const body = parse(ProductInput, req.body, res); if (!body) return;
  const { id: _ignored, ...fields } = body;
  const values = { ...fields, updatedAt: new Date() };
  try {
    const [row] = await inBusiness(req, tx => tx.insert(products).values({ id, businessId: businessIdOf(req), ...values })
      .onConflictDoUpdate({ target: products.id, set: values }).returning());
    res.status(created).json(toProductDto(row!));
  } catch (e) {
    // The id exists in another business: RLS hides it, so it cannot be updated from here.
    if (pgCode(e) === '42501' || pgCode(e) === PG.uniqueViolation) return res.status(409).json({ code: 'CONFLICT', message: 'This id is already in use.' });
    throw e;
  }
}

productRoutes.post('/', canWrite, (req, res) => save(req, res, req.body?.id ?? 'p_' + crypto.randomUUID(), 201));
productRoutes.put('/:id', canWrite, (req, res) => save(req, res, param(req, 'id'), 200));

productRoutes.delete('/:id', canWrite, async (req, res) => {
  const rows = await inBusiness(req, tx => tx.delete(products).where(eq(products.id, param(req, 'id'))).returning({ id: products.id }));
  return rows.length ? res.status(204).end() : notFound(res, 'Product');
});
